import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/http-api.md","filePath":"reference/http-api.md","lastUpdated":1793093713000}'),i={name:"reference/http-api.md"};function n(r,t,s,c,h,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h1><p>Both brains serve the same API on <code>127.0.0.1:8790</code> (<code>FROGHUB_PORT</code>). Caddy passes <code>/api/*</code> on to it from your site; <code>/local/*</code> is only reachable from the server itself.</p><p><strong>Admin only</strong> routes need an <code>X-Admin-Token</code> header: <code>POST /api/admin/unlock {&quot;pin&quot;: &quot;1234&quot;}</code> returns one, and it expires after a while. Too many wrong PINs lock it for a few minutes.</p><h2 id="asking" tabindex="-1">Asking <a class="header-anchor" href="#asking" aria-label="Permalink to &quot;Asking&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>POST /api/ask</code></td><td>A question from a display: <code>{text, personality, speaker, device, conversation_id, devices}</code>. Returns <code>{text, continue_conversation, actions, display?}</code></td></tr><tr><td><code>POST /api/admin/remember</code></td><td>The admin page asking the assistant to remember, change or forget something: <code>{text}</code>. Admin only</td></tr></tbody></table><h2 id="announcements-and-displays" tabindex="-1">Announcements and displays <a class="header-anchor" href="#announcements-and-displays" aria-label="Permalink to &quot;Announcements and displays&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>POST /local/announce</code></td><td>Say something on the displays: <code>{say, show?}</code>, <code>{prompt}</code>, <code>{audio, title?}</code> or <code>{stop_audio: true}</code>, with optional <code>to</code>, <code>area</code>, <code>at_night</code>, <code>personality</code>. See <a href="/features/announcements">Announcements</a></td></tr><tr><td><code>POST /api/announce</code></td><td>A display&#39;s 📢 message: <code>{text, to?, device, name}</code></td></tr><tr><td><code>POST /api/admin/announce</code></td><td>An announcement from the admin page. Admin only</td></tr><tr><td><code>GET /api/announcements?after=&amp;device=&amp;name=&amp;area=</code></td><td>Each display&#39;s poll (every 5 s): new announcements, plus anything queued for it as <code>command</code></td></tr><tr><td><code>GET /api/displays</code></td><td>The displays that are on</td></tr><tr><td><code>GET /api/admin/displays</code></td><td>Every display that has ever checked in. Admin only</td></tr><tr><td><code>POST /api/admin/displays</code></td><td><code>{id, action: wipe | welcome | forget | cancel | set, set?}</code>. Admin only</td></tr></tbody></table><h2 id="alarms" tabindex="-1">Alarms <a class="header-anchor" href="#alarms" aria-label="Permalink to &quot;Alarms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>GET /api/alarms</code></td><td>The alarms and timers</td></tr><tr><td><code>POST /api/alarms/done</code></td><td>Stop a ringing one: <code>{id}</code></td></tr><tr><td><code>POST /api/alarms/snooze</code></td><td>Snooze a ringing one for 9 minutes: <code>{id}</code></td></tr><tr><td><code>POST /api/alarms/manage</code></td><td><code>{tool: set_alarm | set_timer | cancel_alarm, args}</code>, with the same rules as the assistant&#39;s tools. Admin only</td></tr></tbody></table><h2 id="settings-and-policy" tabindex="-1">Settings and policy <a class="header-anchor" href="#settings-and-policy" aria-label="Permalink to &quot;Settings and policy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>GET /api/instance</code></td><td>The house: <code>{site, haUrl, timeZone, kids}</code></td></tr><tr><td><code>GET /api/policy</code> / <code>POST</code></td><td>What the assistant may use. Posting is admin only</td></tr><tr><td><code>GET /api/settings</code> / <code>POST</code></td><td>Settings shared by every display (the Home Assistant token only with <code>X-Admin-Token</code>). Posting is admin only</td></tr><tr><td><code>GET /api/audience?device=</code> / <code>POST {device, grownUps}</code></td><td>Whether a display is a grown-ups&#39; one. Posting is admin only</td></tr></tbody></table><h2 id="radio-and-lists" tabindex="-1">Radio and lists <a class="header-anchor" href="#radio-and-lists" aria-label="Permalink to &quot;Radio and lists&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>GET /api/radio/&lt;id&gt;</code></td><td>The stream of an http-only station <code>play_radio</code> chose, relayed for the https page. Ids last a day</td></tr><tr><td><code>GET /api/admin/lists</code></td><td>Home Assistant&#39;s to-do lists: <code>{lists: [{id, name, items, allowed}]}</code>. Admin only</td></tr><tr><td><code>POST /api/admin/lists {allowed: [ids]}</code></td><td>Which lists the assistant may use. Admin only</td></tr></tbody></table><h2 id="pairing" tabindex="-1">Pairing <a class="header-anchor" href="#pairing" aria-label="Permalink to &quot;Pairing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>POST /api/pair</code></td><td>A new pairing code for a display&#39;s QR code: <code>{code}</code></td></tr><tr><td><code>GET /api/pair?code=</code></td><td><code>{waiting: true}</code> until a grown-up approves it, then the shared settings and token, once</td></tr><tr><td><code>POST /api/admin/pair {code}</code></td><td>Approve it. Admin only</td></tr></tbody></table><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>What it does</th></tr></thead><tbody><tr><td><code>POST /api/admin/unlock {pin}</code></td><td>An admin token</td></tr><tr><td><code>GET /api/admin/check</code></td><td><code>{admin}</code>: whether the token is still good</td></tr><tr><td><code>POST /api/admin/lock</code></td><td>End admin mode</td></tr><tr><td><code>GET /api/admin/memory</code></td><td>The assistant&#39;s memory files: <code>[{file, text, modified}]</code>. Admin only</td></tr><tr><td><code>GET /api/admin/history?before=&amp;limit=</code></td><td>The <a href="/guide/grown-ups#history">History</a>, newest first: <code>{items, more}</code>. Admin only</td></tr><tr><td><code>POST /api/admin/history {clear: true}</code></td><td>Clear it. Admin only</td></tr><tr><td><code>POST /api/wakeword/sample?kind=wake|other&amp;speaker=</code></td><td>A wake word recording (raw 16-bit 16 kHz mono PCM). Admin only</td></tr><tr><td><code>GET /api/wakeword/counts</code></td><td>How many recordings there are. Admin only</td></tr><tr><td><code>GET /api/ping</code></td><td>Whether the server is up</td></tr></tbody></table>',17)])])}const y=e(i,[["render",n]]);export{p as __pageData,y as default};
